package nl.timtoys.corruptedadventure.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.levelgen.placement.PlacedFeature;
import nl.timtoys.corruptedadventure.CorruptedAdventure;

/**
 * Keys of the mod's placed features. The features themselves are datapack entries, generated by datagen.
 */
public final class ModPlacedFeatures {
    public static final ResourceKey<PlacedFeature> WITHERED_EXPANSE_TREES = key("withered_expanse_trees");
    public static final ResourceKey<PlacedFeature> WITHERED_EXPANSE_VEGETATION = key("withered_expanse_vegetation");
    public static final ResourceKey<PlacedFeature> WITHERED_EXPANSE_ROCKS = key("withered_expanse_rocks");
    public static final ResourceKey<PlacedFeature> WITHERED_EXPANSE_SAND_PATCHES = key("withered_expanse_sand_patches");
    public static final ResourceKey<PlacedFeature> BARE_PATCH = key("bare_patch");
    public static final ResourceKey<PlacedFeature> UNNATURAL_TUNNEL = key("unnatural_tunnel");
    public static final ResourceKey<PlacedFeature> SOUL_CRYSTAL_ORE = key("soul_crystal_ore");
    public static final ResourceKey<PlacedFeature> CRIMSON_SOUL_CRYSTAL_ORE = key("crimson_soul_crystal_ore");
    // Ring 2, in the order of their biome's feature lists (Ring2Biomes).
    public static final ResourceKey<PlacedFeature> CANYON_BOULDER_FIELDS = key("canyon_boulder_fields");
    public static final ResourceKey<PlacedFeature> CANYON_TALUS_RUBBLE = key("canyon_talus_rubble");
    public static final ResourceKey<PlacedFeature> CANYON_ROCKFALL = key("canyon_rockfall");
    public static final ResourceKey<PlacedFeature> PLATEAU_RUBBLE = key("plateau_rubble");
    public static final ResourceKey<PlacedFeature> CANYON_SPRINGS = key("canyon_springs");
    public static final ResourceKey<PlacedFeature> CANYONLANDS_VEGETATION = key("canyonlands_vegetation");
    public static final ResourceKey<PlacedFeature> OASIS_ROCKS = key("oasis_rocks");
    public static final ResourceKey<PlacedFeature> OASIS_SHORE_CANE = key("oasis_shore_cane");
    public static final ResourceKey<PlacedFeature> OASIS_SHORE_PLANTS = key("oasis_shore_plants");
    public static final ResourceKey<PlacedFeature> OASIS_PALM_GROVES = key("oasis_palm_groves");
    public static final ResourceKey<PlacedFeature> OASIS_PALMS_SAND = key("oasis_palms_sand");
    public static final ResourceKey<PlacedFeature> OASIS_PALM_BUSHES = key("oasis_palm_bushes");
    public static final ResourceKey<PlacedFeature> OASIS_VEGETATION = key("oasis_vegetation");
    public static final ResourceKey<PlacedFeature> OASIS_TRANSITION_VEGETATION = key("oasis_transition_vegetation");
    // Ring 2 extra biomes (change 30).
    public static final ResourceKey<PlacedFeature> HOODOO_FIELDS_VEGETATION = key("hoodoo_fields_vegetation");
    public static final ResourceKey<PlacedFeature> SALT_FLATS_CRYSTALS = key("salt_flats_crystals");
    public static final ResourceKey<PlacedFeature> DUNE_SEA_VEGETATION = key("dune_sea_vegetation");
    // Ring 2 salt and dune shapes and water (change 30b, Ring2FlatsFeatures), in the order of their biome's lists.
    public static final ResourceKey<PlacedFeature> SALT_FLATS_BRINE_POOLS = key("salt_flats_brine_pools");
    public static final ResourceKey<PlacedFeature> SALT_FLATS_PILLAR_FIELDS = key("salt_flats_pillar_fields");
    public static final ResourceKey<PlacedFeature> SALT_FLATS_PILLARS = key("salt_flats_pillars");
    public static final ResourceKey<PlacedFeature> SALT_ISLAND_ROCKS = key("salt_island_rocks");
    public static final ResourceKey<PlacedFeature> SALT_FLATS_CRYSTAL_FIELDS = key("salt_flats_crystal_fields");
    public static final ResourceKey<PlacedFeature> DUNE_SEA_OASES = key("dune_sea_oases");
    public static final ResourceKey<PlacedFeature> DUNE_SEA_OUTCROPS = key("dune_sea_outcrops");
    // Ring 2 ores (change 25). The tapered vanilla ores (ring_2/ore_*) have no constants: RingVanillaOres.keys.
    public static final ResourceKey<PlacedFeature> SUNSTONE_ORE = key("sunstone_ore");
    public static final ResourceKey<PlacedFeature> TURQUOISE_ORE = key("turquoise_ore");
    // Vanilla's soft disks with a chunk-local origin (change 26), in vanilla's order.
    public static final ResourceKey<PlacedFeature> RING_2_DISK_SAND = key("ring_2/disk_sand");
    public static final ResourceKey<PlacedFeature> RING_2_DISK_CLAY = key("ring_2/disk_clay");
    public static final ResourceKey<PlacedFeature> RING_2_DISK_GRAVEL = key("ring_2/disk_gravel");

    private ModPlacedFeatures() {
    }

    private static ResourceKey<PlacedFeature> key(String path) {
        return ResourceKey.create(Registries.PLACED_FEATURE, CorruptedAdventure.id(path));
    }
}
